	// Placement-heap resources inherit the heap's hazard tracking; strip
	// hazard bits and pass storage/cache + untracked only.
	MTL::ResourceOptions heap_options = (options & (RESOURCE_STORAGE_MODE_MASK | RESOURCE_CPU_CACHE_MODE_MASK)) | MTL::ResourceHazardTrackingModeUntracked;

